using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly Dictionary<string, object> _config = new()
    {
        ["appName"] = "MyService",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    [McpServerResource(UriTemplate = "config://app", Name = "app-config")]
    [Description("Returns the current application configuration as JSON")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(_config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/{section}", Name = "app-config-section")]
    [Description("Returns a specific configuration section value")]
    public static string GetConfigSection(string section)
    {
        if (_config.TryGetValue(section, out var value))
        {
            return JsonSerializer.Serialize(value);
        }
        return $"Configuration section '{section}' not found.";
    }
}

